    "meaning": "sich trauen, wagen (Mut zu einer Handlung)",
    "formation": "Subjekt + (不/没) 敢 + Verb",
    "notes": "Das Adjektiv 勇敢 (yǒnggǎn) „mutig“ beschreibt eine Eigenschaft, 敢 die Bereitschaft zu einer Handlung. Vergleich: 我不会游泳 (wǒ bú huì yóuyǒng) „ich kann nicht schwimmen“ – 我不敢游泳 (wǒ bù gǎn yóuyǒng) „ich traue mich nicht zu schwimmen“.",
    "explanation": "Das Modalverb 敢 (gǎn) drückt aus, dass jemand den Mut zu einer bestimmten Handlung hat: „sich trauen, wagen“. Es steht vor einem Verb bzw. einer Verbgruppe. Sehr häufig ist die Verneinung 不敢 (bù gǎn) „sich nicht trauen“; bezogen auf eine vergangene Situation sagt man 没敢 (méi gǎn) „hat sich nicht getraut“. Fragen bildet man mit 敢不敢 (gǎn bu gǎn) oder mit 吗, und 敢 kann allein als kurze Antwort stehen: 敢！ „Trau ich mich!“. 我不敢说 (wǒ bù gǎn shuō) kann auch vorsichtig „ich kann es nicht mit Sicherheit sagen“ bedeuten. Typischer Fehler: 敢 mit 会 (huì) oder 能 (néng) verwechseln – diese fragen nach Können oder Möglichkeit, nicht nach Mut.",
