    "explanation": "Diese Pronomen weisen auf Personen oder Dinge einer Gruppe hin; die meisten klingen etwas formeller als 这 (zhè) oder 每 (měi).\n各 (gè) – „jeder einzelne, die verschiedenen“; steht direkt vor einem Nomen oder einigen Zählwörtern: 各国 (gè guó) „alle Länder“, 各班 (gè bān) „jede Klasse“. Oft folgt 都 (dōu).\n各位 (gèwèi) – höfliche Anrede an eine Gruppe: 各位老师 (gèwèi lǎoshī) „liebe Lehrerinnen und Lehrer“; allein etwa „meine Damen und Herren“.\n各种 (gèzhǒng) – „alle möglichen, verschiedenste“: 各种水果 (gèzhǒng shuǐguǒ) „alle möglichen Obstsorten“.\n任何 (rènhé) – „jeder beliebige, irgendein“; meist ohne Zählwort direkt vor dem Nomen (mit Zählwort nur zusammen mit 一: 任何一个人, rènhé yí ge rén), oft mit 都/也 oder einer Verneinung: 没有任何问题 (méiyǒu rènhé wèntí) „überhaupt kein Problem“.\n此 (cǐ) – schriftsprachlich „dies, dieser, hier“: 此时 (cǐshí) „in diesem Moment“; auch allein nach Präpositionen: 对此 (duì cǐ) „hierzu“.",
