    "formation": "此 + Nomen/Zählwort · Präposition + 此 (对此、为此、从此、在此)",
    "notes": "此 ist auch Teil des Überblicks der hinweisenden Pronomen (HSK 4: 各, 各位 (gèwèi), 各种 (gèzhǒng), 任何 (rènhé), 此). Feste Verbindungen mit eigenen Punkten: 此外 (cǐwài) „außerdem“ (HSK 4), 如此 (rúcǐ) „so, derart“ (HSK 5), 就此 (jiùcǐ) „hiermit“ (HSK 7–9).",
    "explanation": "此 (cǐ) ist das schriftsprachliche Gegenstück zu 这 (zhè) „dies, dieser“. Es steht direkt vor einem meist einsilbigen Nomen oder Zählwort: 此人 (cǐ rén) „diese Person“, 此时 (cǐshí) „jetzt, in diesem Moment“, 此次 (cǐ cì) „dieses Mal“, 此处 (cǐ chù) „hier“. Anders als 这 kann es allein nach einer Präposition stehen und vertritt dann einen vorher genannten Sachverhalt: 对此 (duì cǐ) „dazu, hierzu“, 为此 (wèi cǐ) „dafür, deshalb“, 从此 (cóngcǐ) „von da an“, 在此 (zài cǐ) „hier, an dieser Stelle“. 此 begegnet vor allem in Nachrichten, auf Schildern, in Briefen und Reden; im Alltag sagt man meist 这 oder 这个 (zhège). Viele feste Wörter enthalten es, etwa 因此 (yīncǐ) „deshalb“.",
