    "explanation": "Viele Nomen können als Zählwort „ausgeliehen“ werden. Bei Behältern wie 盒 zählt man den Inhalt. Bei Körperteilen, Räumen und Flächen wie 脸, 手, 屋子 (wūzi) und 桌子 (zhuōzi) steht fast immer 一, und die Bedeutung ist „ganz voll von, über und über“. Zwischen Zählwort und Nomen kann 的 stehen: 一屋子的人 (yì wūzi de rén) „ein Zimmer voller Leute“.\n脸 (liǎn) – „das ganze Gesicht voll“: 一脸汗 (yì liǎn hàn) „schweißüberströmt“; auch für Gesichtsausdrücke: 一脸不高兴 (yì liǎn bù gāoxìng) „sichtlich verärgert“.\n手 (shǒu) – „die ganzen Hände voll“: 一手油 (yì shǒu yóu) „ölverschmierte Hände“; außerdem für Fertigkeiten: 一手好字 (yì shǒu hǎo zì) „eine schöne Handschrift“.\n盒 (hé) – „Schachtel, Dose“: 一盒饼干 (yì hé bǐnggān) „eine Schachtel Kekse“.\n屋子 (wūzi) – „ein Zimmer voll“: 一屋子客人 (yì wūzi kèrén) „ein Zimmer voller Gäste“.\n桌子 (zhuōzi) – „ein Tisch voll“: 一桌子菜 (yì zhuōzi cài) „ein ganzer Tisch voller Gerichte“.",
