    "meaning": "Zählwörter für Handlungen: Vorgang, Mahlzeit/Schelte, Fahrt",
    "formation": "Verb (+ 了) + Zahl + 场/顿/趟 (+ Objekt)",
    "notes": "次 (cì, HSK 2) zählt neutral „Mal“, 遍 (biàn, HSK 3) betont „von Anfang bis Ende“. 趟 zählt dagegen nur Wege, 顿 nur Mahlzeiten und Schelte, 场 einen abgeschlossenen Vorgang.",
    "explanation": "Verbale Zählwörter stehen hinter dem Verb und geben an, wie oft oder in welchem Umfang etwas geschieht. Ein Ortsobjekt kann vor oder nach dem Zählwort stehen: 去一趟北京 (qù yí tàng Běijīng) oder 去北京一趟 (qù Běijīng yí tàng); ein Personalpronomen steht davor: 骂了他一顿 (mà le tā yí dùn).\n场 (cháng) – für einen ganzen Vorgang mit Anfang und Ende, oft Gefühlsausbrüche oder Krankheiten: 哭了一场 (kū le yì cháng) „sich richtig ausgeweint“, 病了一场 (bìng le yì cháng) „eine Zeit lang krank gewesen“. Als Zählwort für Spiele und Vorführungen wird es meist chǎng gesprochen: 一场比赛 (yì chǎng bǐsài).\n顿 (dùn) – für Mahlzeiten sowie Schelte und Schläge: 吃了一顿 (chī le yí dùn) „ordentlich gegessen“, 批评了他一顿 (pīpíng le tā yí dùn) „ihn tüchtig ausgeschimpft“.\n趟 (tàng) – für einen Weg oder eine Fahrt (meist hin und zurück): 去了一趟银行 (qù le yí tàng yínháng) „kurz zur Bank gegangen“, 白跑一趟 (bái pǎo yí tàng) „umsonst hingelaufen“.",
