    "explanation": "Diese Adverbien stehen vor dem Verb (忽然 (hūrán) und 本来 (běnlái) auch am Satzanfang) und ordnen eine Handlung zeitlich ein.\n按时 (ànshí) – „pünktlich, zur vorgesehenen Zeit“: 按时吃药 (ànshí chī yào) „die Medizin wie verordnet nehmen“.\n从来 (cónglái) – „schon immer“; meist verneint: 从来不 (cónglái bù) „nie“ (Gewohnheit), 从来没 (cónglái méi) … 过 „noch nie“ (Erfahrung).\n赶紧 (gǎnjǐn) – „schnell, sofort“, umgangssprachlich, wenn etwas eilt.\n赶快 (gǎnkuài) – „schnell, rasch“, ähnlich wie 赶紧, besonders oft in Aufforderungen: 赶快走吧 (gǎnkuài zǒu ba) „lass uns schnell gehen“.\n已 (yǐ) – „bereits“, schriftsprachliche Kurzform von 已经 (yǐjīng).\n忽然 (hūrán) – „plötzlich, auf einmal“.\n将 (jiāng) – „werden“, schriftsprachliches Futur: 将于明年完成 (jiāng yú míngnián wánchéng) „wird nächstes Jahr fertig“.\n将要 (jiāngyào) – „demnächst werden“, betont, dass etwas bald geschieht.\n从 (cóng) – „nie“ in 从不 (cóng bù) und 从没 (cóng méi), Kurzform von 从来.\n本来 (běnlái) – „ursprünglich, eigentlich“: Es war anders geplant oder ist anders gekommen.",
