    "explanation": "Das Zeitadverb 将 (jiāng) kündigt an, dass etwas in der Zukunft geschehen wird – „werden“. Es ist schriftsprachlich und typisch für Nachrichten, Ankündigungen, Wetterberichte und offizielle Texte; im Alltag sagt man eher 要 (yào), 会 (huì) oder 快要 (kuàiyào). 将 steht direkt vor dem Verb oder vor einer Präposition: 将于 (jiāng yú) + Zeitpunkt „wird am/im …“, 将在 (jiāng zài) + Ort „wird in …“. Gemeint ist meist ein geplantes oder erwartetes Ereignis. Verneint wird mit 将不 (jiāng bù) bzw. 将不再 (jiāng bú zài) „wird nicht mehr“.",
