    "notes": "往往 (wǎngwǎng) gehört auch zum Überblick der Häufigkeitsadverbien HSK 4. 往往 urteilt eher rückblickend und verallgemeinernd, 常常 (chángcháng) ist neutraler und kann auch Zukünftiges beschreiben.",
    "explanation": "往往 (wǎngwǎng) fasst eine Erfahrung zusammen: Unter bestimmten Umständen ist etwas bisher meistens so gewesen – „oft, in der Regel, meist“. Der Satz nennt deshalb gewöhnlich eine Bedingung, Zeit oder Situation, etwa 周末的时候 (zhōumò de shíhou) „am Wochenende“. 往往 beschreibt Tatsachen und Regelmäßigkeiten; für einen Wunsch, eine Aufforderung oder die Zukunft passt es nicht – dort steht 常常 (chángcháng) oder 经常 (jīngcháng): 以后要常常来 (yǐhòu yào chángcháng lái) „komm künftig öfter“, nicht *以后要往往来. Auch für eine bloße persönliche Gewohnheit ohne jeden Umstand klingt 常常 natürlicher.",
