    "explanation": "Diese Adverbien beschreiben, wie eine Handlung ausgeführt wird; sie stehen nach dem Subjekt vor dem Prädikat.\n故意 (gùyì) – „absichtlich, mit Absicht“; meist bei etwas Unangenehmem (他故意不说). Die Verneinung „keine Absicht“ lautet 不是故意的.\n互相 (hùxiāng) – „gegenseitig, einander“; das Subjekt bezeichnet mehrere Personen (我们互相帮助). Nur als Adverb vor dem Verb.\n相互 (xiānghù) – ebenfalls „gegenseitig“, aber formeller und eher geschrieben; anders als 互相 kann es auch ein Nomen näher bestimmen: 相互关系 (xiānghù guānxi) „wechselseitige Beziehung“.",
