    "formation": "Teilsatz 1，(Subjekt +) 却 + Prädikat",
    "notes": "Im Satzpaar 虽然 (suīrán) ……，却…… „obwohl …, (doch) …“ steht 却 als Gegenstück zu „obwohl“; das gehört zum eigenen Punkt 虽……，但/可/却/也…… (HSK 6).",
    "explanation": "却 (què) verbindet zwei Aussagen, die einander widersprechen oder bei denen die zweite unerwartet ist: „aber, jedoch, dagegen“. Anders als 但是 (dànshì) ist 却 ein Adverb: Es steht im zweiten Teilsatz nach dem Subjekt direkt vor dem Prädikat (他却不来), nie vor dem Subjekt – *却他不来 ist falsch. Haben beide Teilsätze dasselbe Subjekt, folgt 却 direkt auf das Komma. 却 lässt sich mit 但是 oder 可是 (kěshì) kombinieren (但是他却……) und verstärkt dann den Gegensatz. Es klingt etwas gehobener als 可是 und ist in Erzählungen und geschriebenen Texten häufig.",
