    "formation": "Subjekt + 并 + 不/没（有） + Prädikat",
    "notes": "并² ist eine Konjunktion „und (außerdem)“, die Verben oder Verbgruppen verbindet (讨论并通过); siehe den HSK-4-Punkt „连接词或词组“. Gehoben verwandt: 并非 (bìngfēi) „keineswegs sein“.",
    "explanation": "并 (bìng) steht direkt vor 不 oder 没（有） und verstärkt die Verneinung: „keineswegs, gar nicht, eigentlich nicht“. Damit wird meist eine Annahme oder Erwartung zurückgewiesen – man könnte denken, dass …, in Wirklichkeit ist es aber nicht so. Oft steht deshalb ein Gegensatz im Kontext (看起来很难，其实并不难). Ohne folgende Verneinung hat 并 diese Bedeutung nicht. Gegenüber 根本 (gēnběn) „überhaupt nicht“, das schärfer und emotionaler verneint, klingt 并 sachlicher und richtigstellend.",
