    "notes": "只能 (zhǐ néng) „kann nur“ ist fast gleichbedeutend. 不得不 (bùdébù) „muss notgedrungen“ betont den äußeren Zwang stärker.",
    "explanation": "只好 (zhǐhǎo) zeigt, dass jemand etwas tut, weil es keine bessere Möglichkeit gibt: „bleibt nichts anderes übrig, als …; notgedrungen“. Meist nennt der erste Teilsatz den Umstand, der zu dieser Entscheidung zwingt (没有票了，我们只好……). 只好 steht nach dem Subjekt direkt vor dem Verb. Es beschreibt eine bereits getroffene oder feststehende Entscheidung und klingt eher resigniert-sachlich. Obwohl es aus 只 „nur“ und 好 „gut“ besteht, hat 只好 nichts mit „gut“ zu tun – es ist ein eigenes Wort.",
