    "notes": "居然 (jūrán) ist fast gleichbedeutend (HSK 5) und etwas umgangssprachlicher. 果然 (guǒrán) meint das Gegenteil: „wie erwartet“.",
    "explanation": "竟然 (jìngrán) zeigt, dass ein Sachverhalt den Erwartungen des Sprechers widerspricht: „wider Erwarten, tatsächlich, zu meiner Überraschung“. Die Überraschung kann positiv oder negativ sein. 竟然 steht meist nach dem Subjekt direkt vor dem Prädikat (他竟然……). Es bezieht sich auf Tatsachen – Geschehenes oder Bestehendes –, nicht auf Pläne oder Wünsche. Oft steht 没想到 (méi xiǎngdào) „unerwartet“ davor, oder 竟然 erscheint in einer empörten Frage (你竟然不知道？). Geschrieben gibt es auch die Kurzform 竟 (jìng).",
