    "explanation": "究竟 (jiūjìng) verstärkt Fragen, mit denen man der Sache auf den Grund gehen will: „eigentlich, denn nun, letztlich“. Wie 到底 (dàodǐ) steht es in Fragen mit Fragewort, in A-不-A-Fragen oder in Alternativfragen mit 还是 (háishi), nicht aber in Fragen mit 吗. Ist das Fragewort selbst das Subjekt, steht 究竟 am Satzanfang (究竟谁说得对？). Auch in indirekten Fragen ist es üblich. 究竟 klingt gehobener und sachlicher als 到底 und ist in Texten, Berichten und ernsthaften Gesprächen häufig; 到底 wirkt umgangssprachlicher und oft ungeduldig.",
