    "explanation": "Die Präposition 当 (dāng) leitet einen Zeitrahmen ein: „als, wenn, während, in dem Moment, in dem …“. Sie bildet fast immer einen Rahmen mit 的时候 (de shíhou) oder, gehobener, mit 时 (shí): 当……的时候 / 当……时. Dazwischen steht ein ganzes Ereignis mit Subjekt und Verb. Die Zeitangabe steht vor dem Hauptsatz, meist am Satzanfang. 当 macht den Satz etwas förmlicher; im Alltag genügt oft ……的时候 allein. Typischer Fehler: 当 ohne abschließendes 的时候 oder 时 (*当我回家，……) klingt unvollständig.",
