    "notes": "Das Zeitadverb 将 „werden“, auch 将要 (jiāngyào), ist ein eigener Punkt (时间副词, HSK 4). Zu 由¹ „von, aus“ siehe den HSK-4-Punkt zu Präpositionen für Zeit und Ort.",
    "explanation": "Diese Präpositionen markieren, wer handelt oder was behandelt wird.\n将 (jiāng) – schriftsprachliche Entsprechung von 把 (bǎ): holt das Objekt vor das Verb, z. B. in Anweisungen und Durchsagen (请将手机关上 „bitte das Handy ausschalten“).\n由² (yóu) – nennt, wer für eine Aufgabe zuständig ist oder sie ausführt: 这件事由我负责 „dafür bin ich zuständig“. Das Behandelte steht meist am Satzanfang.\n叫 (jiào) – umgangssprachliche Passivmarke wie 被 (bèi): 自行车叫人借走了. Anders als bei 被 muss der Handelnde genannt werden, notfalls 人 „jemand“.\n让 (ràng) – ebenfalls umgangssprachliches Passiv, auch hier immer mit Handelndem: 蛋糕让弟弟吃了.\n叫 und 让 bedeuten außerdem „veranlassen, lassen“; welche Lesart gemeint ist, zeigt der Kontext.",
