    "explanation": "Als Präposition steht 由于 (yóuyú) vor einer Nominalgruppe und nennt die Ursache: „aufgrund von, wegen, infolge“. Die Ursachenangabe steht meist am Satzanfang und wird durch ein Komma abgetrennt (由于大雾，……). Typische feste Wendungen sind 由于……原因 (yuányīn) „aus … Gründen“ und 由于……关系 (guānxi) „wegen …“. 由于 klingt formeller als 因为 (yīnwèi) und ist in Nachrichten, Durchsagen und geschriebenen Texten häufig. Folgt statt einer Nominalgruppe ein ganzer Satz (由于天气不好，……), ist 由于 eine Konjunktion (由于², eigener Punkt).",
