    "explanation": "对于 (duìyú) führt die Sache oder Person ein, auf die sich eine Aussage, Haltung oder Bewertung bezieht: „hinsichtlich, in Bezug auf, gegenüber, für“. Die Gruppe steht am Satzanfang (对于这个问题，……) oder nach dem Subjekt vor dem Prädikat (我们对于这个问题……). Fast immer kann 对于 durch 对 (duì) ersetzt werden; 对于 ist formeller. Umgekehrt geht das nicht immer: Wo 对 eine Person bezeichnet, der gegenüber man direkt handelt (他对我笑了 „er lächelte mich an“), ist 对于 nicht möglich. Häufige Verbindung: 对于……来说 „für … (aus Sicht von)“.",
