    "explanation": "而 (ér) verbindet hier zwei Adjektive oder Verbphrasen innerhalb eines Satzes. Meist sind beide Teile gleichgerichtet: „und (zugleich)“, etwa 干净而安静 „sauber und ruhig“ oder 安全而方便 „sicher und bequem“. Stehen sie im Gegensatz, bedeutet es „aber, und dabei“, oft in der Form A而不B: 漂亮而不贵 „hübsch und dabei nicht teuer“. 而 klingt gehoben und schriftlich; im Gespräch sagt man eher 又……又…… oder 而且 (érqiě). Anders als 和 (hé) verbindet 而 keine Nomen: Zwei Personen oder Dinge reiht man mit 和 aneinander, nicht mit 而. Die beiden verbundenen Teile sind meist ähnlich lang und gleich gebaut.",
