    "notes": "此外 (cǐwài) vs. 另外 (lìngwài): Als Konjunktion („außerdem“) sind beide meist austauschbar; 另外 kann aber auch „andere(r)“ (另外的办法) oder „zusätzlich, extra“ vor einem Verb bedeuten. 而且 (érqiě) steigert („und sogar noch“) und braucht einen engen Bezug zum ersten Teil, 此外 reiht nur einen weiteren Punkt an.",
