    "meaning": "Satzverbindende Konjunktionen (HSK 4): nicht nur, außerdem, wenn, deshalb, weil, hinzu kommt",
    "notes": "Als Präposition vor einem Nomen heißt 由于 (yóuyú) „aufgrund von“ (由于¹, eigener Punkt). Die zugehörigen Satzmuster („nicht nur …, sondern auch …“, „wenn …, dann …“, „weil …, deshalb …“) werden jeweils einzeln behandelt.",
    "explanation": "Diese Konjunktionen verbinden Teilsätze und zeigen Steigerung, Ergänzung, Bedingung, Grund oder Folge.\n不光 (bùguāng) – „nicht nur“; umgangssprachlich, im zweiten Teil folgt 还, 也 oder 而且 (érqiě).\n不仅 (bùjǐn) – „nicht nur“; neutral bis schriftlich, meist mit 而且 oder 还 im zweiten Teil.\n另外 (lìngwài) – „außerdem“; fügt einen weiteren Punkt hinzu, im Gespräch wie im Text üblich.\n要是 (yàoshi) – „wenn, falls“; umgangssprachlich, im Folgesatz meist 就.\n因此 (yīncǐ) – „deshalb, daher“; leitet die Folge ein, eher schriftlich.\n由于 (yóuyú) – hier als Konjunktion (由于²): „weil, da“; am Anfang des Grundsatzes, oft mit 因此 oder 所以 (suǒyǐ) im Folgesatz; eher schriftlich.\n加上 (jiāshàng) – „hinzu kommt, dazu“; fügt einen weiteren Umstand (meist einen weiteren Grund) an, danach oft 所以 oder 因此.",
