    "explanation": "另外 (lìngwài) leitet als Konjunktion etwas Zusätzliches ein: „außerdem, dazu noch, und noch etwas“. Es steht am Anfang eines Teilsatzes oder Satzes, nach Komma oder Punkt, häufig gefolgt von 还, 也 oder 再. Typisch ist es beim Aufzählen von Wünschen, Hinweisen oder Aufgaben: Man nennt den ersten Punkt und hängt mit 另外 den nächsten an. 另外 ist im Gespräch wie in Texten gebräuchlich und etwas weniger formell als 此外 (cǐwài). Wichtig: 另外 ist kein Nomen-Attribut wie 别的 (bié de): „andere Sachen“ heißt 别的东西; 另外 vor einem Nomen braucht meist ein Zahl- oder Zählwort (另外一个人) oder 的.",
