    "formation": "Attribut + 之 + Nomen; Nenner + 分之 + Zähler (Bruch, Prozent)",
    "notes": "In klassischen Wendungen ist 之 auch ein Pronomen („es, ihn“), etwa in 总之 (zǒngzhī) „kurzum“ oder 学而时习之. Muster wie 之所以 (zhīsuǒyǐ)……是因为…… und (在)……之余 sind eigene Punkte.",
    "explanation": "之 (zhī) stammt aus dem klassischen Chinesisch und entspricht als Partikel dem modernen 的: Es verbindet ein Attribut mit dem Nomen, das es näher bestimmt. Frei verwenden kann man es heute nicht – es steht in festen Ausdrücken und in gehobener Schriftsprache, oft in kurzen, rhythmischen Verbindungen wie 成功之路 „der Weg zum Erfolg“. Im Alltag sehr häufig sind: Brüche und Prozente (三分之一 (sān fēn zhī yī) „ein Drittel“, 百分之五十 (bǎi fēn zhī wǔshí) „50 Prozent“ – erst der Nenner, dann der Zähler), 之一 (zhī yī) „einer/eines von“ nach einer Gruppe, sowie Orts- und Zeitwörter wie 之间 (zhī jiān) „zwischen“, 之前 (zhīqián) „vor“, 之后 (zhīhòu) „nach“. Typische Fehler: 之 im Gespräch einfach für 的 einsetzen, und bei Brüchen die Reihenfolge vertauschen.",
