    "notes": "啊¹ (HSK 2) ist die tonlose Satzendpartikel a (你好啊！), die je nach vorangehendem Laut auch als 呀, 哇 oder 哪 geschrieben wird. 嗯 (HSK 4) drückt dagegen eher Zustimmung, Zuhören oder Nachfragen aus.",
    "explanation": "Als Interjektion steht 啊 allein oder am Anfang eines Satzes und wird durch Komma, Frage- oder Ausrufezeichen abgetrennt. Die Bedeutung hängt vom Ton ab: ā drückt Staunen oder Bewunderung aus („ah!“), á fragt nach oder zeigt, dass man etwas nicht verstanden hat („hm? was?“), ǎ zeigt verwunderten Zweifel („wie bitte, wirklich?“), à drückt Zustimmung oder plötzliches Verstehen aus („ach so!, ah ja“). Im Schriftbild sieht man den Ton nicht; er ergibt sich aus dem Zusammenhang und den Satzzeichen. 啊 gehört vor allem in die gesprochene Sprache und in Dialoge.",
