    "explanation": "In diesem Vierwortmuster stehen zwei einsilbige Wörter jeweils nach 一. Sind A und B verwandte Nomen, betont es jedes noch so kleine Teil: 一言一行 (yì yán yì xíng) „jedes Wort und jede Tat“, 一草一木 „jeder Grashalm und jeder Baum“. Sind A und B gegensätzlich oder ergänzen sich, beschreibt es zwei Teile, die zusammengehören oder sich abwechseln: 一问一答 „Frage und Antwort im Wechsel“, 一前一后 „einer vorn, einer hinten“, 一左一右 „links und rechts“. Bei bedeutungsgleichen Wörtern verstärkt es: 一心一意 (yìxīn-yíyì) „mit ganzem Herzen“. Die Ausdrücke sind weitgehend fest und klingen etwas gehoben. Achtung auf den Ton von 一: yí vor dem vierten, yì vor den anderen Tönen.",
