    "notes": "Gegenstück ist 有A有B („sowohl … als auch“). 没A没B (HSK 5) ist umgangssprachlicher und oft abwertend (没完没了 (méiwán-méiliǎo) „endlos“). 无A不B (HSK 7–9) bedeutet dagegen „alle ohne Ausnahme“.",
    "explanation": "无 (wú) ist das schriftsprachliche „nicht haben, ohne“ und entspricht 没有 (méiyǒu). Doppelt gesetzt mit zwei bedeutungsverwandten Wörtern verstärkt es die Verneinung: „ganz und gar ohne“. So entstehen feste, idiomartige Vierwortausdrücke, die wie Adjektive (mit 的 vor einem Nomen), als Adverbial (mit 地) oder als Prädikat bzw. Komplement stehen. Sie sind nicht frei bildbar, sondern werden als Ganzes gelernt, z. B. 无忧无虑 (wúyōu-wúlǜ) „sorglos“, 无缘无故 (wúyuán-wúgù) „ohne jeden Grund“, 无影无踪 (wúyǐng-wúzōng) „spurlos“, 无边无际 (wúbiān-wújì) „grenzenlos“, 无声无息 (wúshēng-wúxī) „lautlos, unbemerkt“. Der Ton ist gehoben, die gängigen Ausdrücke hört man aber auch im Alltag.",
