    "notes": "Nicht verwechseln mit 又A又B: Das beschreibt zwei Eigenschaften, die ein und dieselbe Sache gleichzeitig hat (又大又甜). 有大有小 setzt dagegen mehrere Dinge voraus. Gegenstück: 无A无B „ganz ohne“.",
    "explanation": "Das Muster hat zwei Hauptgebrauchsweisen. Sind A und B verwandte Wörter, betont es, dass beides reichlich vorhanden ist und etwas dadurch lebendig oder vollständig wirkt: 有说有笑 (yǒushuō-yǒuxiào) „plaudernd und lachend“, 有声有色 (yǒushēng-yǒusè) „lebendig, anschaulich“, 有头有尾 (yǒutóu-yǒuwěi) „mit Anfang und Ende“. Sind A und B Gegensätze, heißt es „teils …, teils …“, es gibt also eine Mischung: 有大有小 „teils groß, teils klein“, 有好有坏 „teils gut, teils schlecht“. Viele Ausdrücke sind fest, mit gegensätzlichen Adjektiven ist das Muster aber recht frei bildbar. Es steht meist als Prädikat, als Komplement nach 得 oder als Adverbial.",
