    "notes": "Die Wörter sind nach dem Muster der Potentialergänzung gebaut (Verb + 得/不 + Ergänzung), vergleichbar mit 赶得上 (gǎndeshàng) / 赶不上 (gǎnbushàng) „etwas noch erreichen / verpassen“.",
    "explanation": "来得及 (láidejí) bedeutet „es ist noch genug Zeit, man schafft es noch“, 来不及 (láibují) „die Zeit reicht nicht mehr, es ist zu spät“. Beide stehen allein als Prädikat (还来得及, 来不及了！) oder vor der Handlung, für die die Zeit (nicht) reicht: 来不及吃早饭 „keine Zeit mehr zum Frühstücken“. 来得及 steht oft mit 还 („noch“), 来不及 oft mit 了. Die Frage lautet 来得及吗？ oder 来得及来不及？. Erzählt man Vergangenes, folgt oft 就: 他来不及吃早饭就走了 „er ging, ohne noch frühstücken zu können“. Typischer Fehler: die Verneinung mit 不 davor bilden – richtig ist nur 来不及. Anders als 没有时间 (méiyǒu shíjiān) betont 来不及 einen Termin oder Zeitdruck.",
