    "formation": "Subjekt + 为了 + Zweck + 而 + Handlung",
    "notes": "Schriftlich auch verkürzt 为……而……: 为人民而工作. Gleich gebaut ist 因为 (yīnwèi) + Grund + 而 + Folge: 他因为生病而没来 = „er ist wegen Krankheit nicht gekommen“.",
    "explanation": "为了 (wèile) nennt den Zweck, 而 (ér) verbindet ihn mit der Handlung, die diesem Zweck dient: „um … zu …“, „für … (tun)“. Anders als bei 为了……，…… mit Komma steht hier alles in einem Satz; der Zweck geht der Handlung voran, und 而 steht direkt vor dem Verb. Die Form klingt gehoben und ist typisch für geschriebene Sprache, Reden und Nachrichten. Häufig folgen Verben wie 努力 (nǔlì) oder 奋斗 (fèndòu): 为了理想而奋斗 = „für ein Ideal kämpfen“. Typischer Fehler: 而 durch 所以 (suǒyǐ) ersetzen – 所以 leitet eine Folge ein, keinen Zweck.",
