    "explanation": "Zwei Dinge werden jeweils mit 是 wiederholt: X 是 X，Y 是 Y = „X ist X, und Y ist Y“. Der Sprecher betont, dass beide Bereiche verschieden sind und nicht vermischt werden dürfen; danach folgt oft eine Folgerung oder Aufforderung. X und Y sind meist Nomen oder Pronomen, die ein Gegensatzpaar bilden – etwa Arbeit und Privatleben, Freundschaft und Geschäft, du und ich. Das Muster ist umgangssprachlich und klingt bestimmt, oft auch abgrenzend. Fest geworden ist 一是一，二是二 = „genau sein, nichts vermengen, Klartext reden“.",
