    "explanation": "就是了 (jiùshì le) am Satzende stellt die Sache als einfach und erledigt dar: „…, und fertig“, „einfach …“. Sagt der Sprecher es über sich selbst, ist es ein beruhigendes Versprechen oder ein Zugeständnis: 我明天还给你就是了 = „ich geb's dir morgen zurück, versprochen“; 我不说就是了 = „dann sag ich eben nichts“ – das klingt oft leicht gekränkt oder ungeduldig. An andere gerichtet ermuntert es, ohne Zögern zu handeln: 你直接问我就是了 = „frag mich einfach“. Das Muster ist gesprochen und soll dem Gegenüber Bedenken nehmen. Ähnlich, aber neutraler sind 就行了 (jiù xíng le) und 就好了 (jiù hǎo le).",
