    "notes": "Davon zu unterscheiden: 还……呢 in der Bedeutung „noch“ (他还在睡觉呢 = „er schläft noch“) und 还 + Verb + 呢 als Vorwurf, dass jemand etwas trotz der Lage tut (你还笑呢！ = „Du lachst auch noch!“).",
    "explanation": "In 还 (hái) + X + 呢 (ne) ist X meist eine Bezeichnung für eine Rolle, einen Status oder einen Anspruch – etwa Student, großer Bruder, Lehrer. Der Sprecher sagt damit: Jemand wird diesem Anspruch nicht gerecht – „und so was will … sein!“, „von wegen …“. Davor oder danach steht, was nicht dazu passt (连这么简单的字都不认识). Der Ton ist vorwurfsvoll, spöttisch oder enttäuscht; das Muster ist rein umgangssprachlich. Ein Subjekt kann davorstehen (你还哥哥呢). Wichtig: Dieses 还……呢 hat nichts mit „noch“ zu tun.",
