    "explanation": "Beide Gradkomplemente drücken einen sehr hohen Grad aus und stehen nach einem Adjektiv oder einem Verb des Fühlens (想, 气, 担心 (dānxīn)). 死了 (sǐ le) folgt direkt, ohne 得: 累死了 = „todmüde“, 饿死了 = „ich verhungere gleich“. Es übertreibt stark, ist sehr umgangssprachlich und steht meist bei unangenehmen Zuständen, aber auch bei Freude (高兴死了). Ein Pronomen kann dazwischentreten: 气死我了 = „das macht mich wahnsinnig“. 厉害 (lìhai) wird mit 得 angeschlossen: 疼得厉害, 咳嗽得厉害; es klingt sachlicher und beschreibt meist Beschwerden oder starke Gefühle. Beide Formen werden nicht verneint. Nicht verwechseln mit 死 als Ergebniskomplement: 打死 (dǎsǐ) = „totschlagen“.",
