    "explanation": "难道 (nándào) leitet eine rhetorische Frage ein: Der Sprecher erwartet keine Antwort, sondern drückt Erstaunen, Zweifel oder einen Vorwurf aus – „etwa …?“, „soll das heißen, dass …?“. Die Bedeutung ist umgekehrt zur Form: 难道你不知道吗？ = „du weißt es doch!“, 难道这是我的错吗？ = „das ist doch nicht meine Schuld!“. 难道 kann vor oder nach dem Subjekt stehen. Am Satzende steht meist 吗; gesprochen fällt es manchmal weg, schriftlich gibt es auch 难道……不成 (bùchéng). Häufig geht ein Satz voraus, der den Widerspruch begründet (他那么努力，难道……).",
