    "formation": "Frage mit 谁 / 什么 / 哪儿 / 怎么, die eine Aussage meint (oft mit 呢)",
    "notes": "Daneben gibt es rhetorische Fragen mit 难道 (nándào)……吗？ und 不是 (búshì)……吗？. Als festes Muster verwandt: （没）有什么（好）X的 („da gibt es nichts zu …“).",
    "explanation": "Auch Fragepronomen können rhetorische Fragen bilden, die eigentlich eine Aussage sind; eine bejahte Frage meint eine Verneinung und umgekehrt. 谁 (shéi): 谁不想……？ = „jeder will …“, 谁知道 (shéi zhīdào)？ = „wer weiß das schon?“. 什么 (shénme): 有什么 + Adjektiv + 的？ = „überhaupt nicht …“, z. B. 这有什么难的？ = „das ist doch nicht schwer“. 哪儿 (nǎr) oder 哪里 (nǎlǐ) vor einem Verb: „keineswegs“, z. B. 我哪儿知道？ = „woher soll ich das wissen?“. 怎么 (zěnme) + 能/会: Vorwurf oder Zweifel („wie kannst du nur …“). Am Ende steht oft 呢, aber kein 吗. Typischer Fehler: solche Fragen wörtlich zu verstehen und eine Auskunft zu geben.",
