    "explanation": "Die knappste Form des 把-Satzes: Nach dem Verb steht nur 了. Das funktioniert vor allem mit Verben, deren Handlung das Objekt verschwinden lässt oder endgültig verändert: 吃, 喝, 卖, 扔 (rēng), 丢, 忘, 花 („Geld ausgeben“), 关, 换. 了 markiert dann das Ergebnis: 我把那辆旧自行车卖了 „Ich habe das alte Fahrrad verkauft (es ist weg)“. In Aufforderungen heißt 把……了 „weg damit, erledige das“: 把药吃了！ „Nimm die Medizin!“ Bei Verben ohne ein solches Ergebnis klingt das bloße 了 unvollständig (我把书看了) – dort braucht man eine Ergänzung wie 完 (看完了). Verneint wird mit 没 vor 把, meist mit einer Ergänzung statt 了.",
