    "explanation": "不如 (bùrú) heißt wörtlich „nicht herankommen an“: A erreicht B nicht, B ist besser. Ohne Adjektiv bedeutet der Satz allgemein „A ist schlechter als B“: 我画画不如我妹妹 „Im Malen bin ich nicht so gut wie meine Schwester“. Mit Adjektiv nennt man, worin B überlegen ist: 坐公交车不如坐地铁快. Das Adjektiv ist in der Regel positiv oder beschreibt die „größere“ Seite (好, 快, 方便 (fāngbiàn), 暖和 (nuǎnhuo)); ein negatives wie 矮 klingt meist seltsam. Gradwörter wie 很 oder 非常 (fēicháng) stehen nicht davor. Inhaltlich entspricht A 没有 (méiyǒu) B + Adjektiv (HSK 2), 不如 klingt aber etwas formeller und deutlicher wertend.",
