    "explanation": "首先 (shǒuxiān) und 其次 (qícì) gliedern eine Aufzählung von Gesichtspunkten, Gründen oder Bedingungen der Reihe nach: 首先 nennt den ersten, oft wichtigsten Punkt, 其次 den zweiten, häufig etwas weniger wichtigen. Weitere Punkte folgen mit 再次 (zàicì) oder 最后 (zuìhòu). Typisch für Reden, Argumentation und Sachtexte. Im Unterschied zu 首先……，然后 (ránhòu) …… geht es nicht um zeitlich aufeinanderfolgende Handlungen, sondern um eine Ordnung von Punkten. 其次 kann auch allein „zweitrangig, weniger wichtig“ bedeuten: 钱是其次的 „Geld ist zweitrangig“.",
