    "explanation": "然而 (rán'ér) leitet einen Gegensatz zum Vorangehenden ein: „jedoch, doch“. Es ist deutlich schriftsprachlich und steht in Berichten, Erzählungen und Aufsätzen; im Gespräch sagt man meist 但是 (dànshì), 可是 (kěshì) oder 不过 (búguò). 然而 steht am Anfang des zweiten Teilsatzes, vor dem Subjekt, und kann auch einen neuen Satz oder Absatz einleiten. Oft folgt etwas Unerwartetes: Man erwartet das eine, doch es kommt anders. Im ersten Teil kann 虽然 (suīrán) stehen (虽然……，然而……).",
