    "notes": "不管 (bùguǎn) kann auch ein Verb sein: „sich nicht kümmern um“ (这件事我不管 – „Darum kümmere ich mich nicht“). Feste Wendung (HSK 5): 不管怎样说 (bùguǎn zěnyàng shuō) – „wie man es auch dreht“.",
    "explanation": "不管 (bùguǎn) sagt, dass das Ergebnis unter allen Umständen gleich bleibt: „egal ob/wie/wer …“. Nach 不管 steht keine einfache Aussage, sondern etwas Offenes: ein Fragewort (谁, 什么 (shénme), 怎么样 (zěnmeyàng), 多 + Adjektiv), eine Ja-Nein-Form (去不去) oder eine Alternative mit 还是 (háishi). Im zweiten Teil steht 都 oder 也 nach dem Subjekt, vor dem Verb. 不管 ist gesprochener als das gleichbedeutende 无论 (wúlùn). Typischer Fehler: *不管下雨，我都去 – richtig ist 不管下不下雨 oder 不管刮风还是下雨. Auch 或者 (huòzhě) ist in der Alternative falsch.",
