    "explanation": "无论 (wúlùn) bedeutet wie 不管 (bùguǎn) „egal ob/wie/wer …“: Das Ergebnis im zweiten Teil gilt unter allen Bedingungen. Es klingt formeller und ist in geschriebenen Texten häufiger; im Gespräch ist 不管 üblicher. Nach 无论 steht eine offene Bedingung: ein Fragewort (谁, 什么 (shénme), 多 + Adjektiv), eine Alternative mit 还是 (háishi) – oft mit 是 davor: 无论是学生还是老师 – oder eine Ja-Nein-Form. Im zweiten Teil steht 都 oder 也 nach dem Subjekt. Typische Fehler: eine einfache Aussage nach 无论 (*无论天气很冷) oder 或者 (huòzhě) in der Alternative.",
