    "notes": "由于 (yóuyú) als Präposition („aufgrund von“, vor einer Nominalgruppe) ist ein eigener Punkt (由于¹). Ähnlich formell: ……，因而 (yīn'ér) …… (HSK 5).",
    "explanation": "由于 (yóuyú) nennt die Ursache, 因此 (yīncǐ) leitet die Folge ein: „da/weil …, deshalb …“. Das Paar klingt sachlich und formell und steht vor allem in Berichten, Nachrichten und Erklärungen; im Gespräch sagt man eher 因为 (yīnwèi) … 所以 (suǒyǐ) …. 由于 kann wegfallen; dann leitet 因此 allein die Folge ein. 因此 steht am Anfang des zweiten Teilsatzes, vor dem Subjekt, und kann auch einen neuen Satz beginnen. Nach 由于 ist statt 因此 auch 所以 möglich.",
