    "notes": "Markierte 紧缩复句 verwenden ein Paar von Adverbien: 一……就…… (HSK 2), 不……也…… (HSK 4), 再……也…… und 不……不…… (beide HSK 5).",
    "explanation": "Ein 紧缩复句 (jǐnsuō fùjù) ist ein „zusammengezogener“ Satz: Zwei Teilsätze werden ohne Komma und oft ohne eigenes Subjekt zu einem Satz verschmolzen. In der unmarkierten Form fehlen auch Bindewörter wie 如果 (rúguǒ) oder 就; die Beziehung (Bedingung, Folge, Gegensatz) ergibt sich allein aus dem Zusammenhang: 有问题问老师 – „Wenn du Fragen hast, frag den Lehrer.“ 你不去我去 – „Wenn du nicht gehst, gehe ich.“ Solche Sätze sind kurz, typisch gesprochen und wirken knapp, oft wie eine Regel oder Anweisung. Beim Verstehen hilft es, gedanklich ein „wenn“ oder „weil“ einzufügen.",
