    "explanation": "来 (lái) nach einer runden Zahl macht sie zu einer Schätzung: 十来个人 – „etwa zehn Leute“, 二十来岁 – „um die zwanzig Jahre alt“, 一百来块钱 – „rund hundert Yuan“. Die Zahl endet auf null (10, 20, 50, 100, 1000 …), und 来 steht zwischen Zahl und Zählwort. Gemeint ist ungefähr dieser Wert, etwas mehr oder etwas weniger. Der Ausdruck ist typisch für die gesprochene Sprache. Typischer Fehler: 来 nach einer Zahl wie 五 oder 十五 (*五来个) – dafür nimmt man 左右 (zuǒyòu) oder zwei benachbarte Zahlen (五六个).",
