    "explanation": "Drei Wörter machen eine Angabe zur Schätzung, jeweils an einer anderen Stelle: 大约 (dàyuē) steht als Adverb vor der Zahl oder vor dem Verb – „etwa, ungefähr“: 大约五十个人. 左右 (zuǒyòu) steht nach einer Mengen-, Alters- oder Zeitangabe – „circa, um … herum“: 五十个人左右, 三十岁左右, 三点左右. 前后 (qiánhòu) steht vor allem nach einem Zeitpunkt, oft einem Fest oder Datum – „um … herum“: 春节前后, 2000年前后; nach Mengen ist es falsch (*五十个人前后). 大约 und 左右 können zusammen stehen (大约五十个人左右); manche halten das für doppelt, im Alltag ist es aber häufig. Alle drei sind gesprochen wie geschrieben üblich.",
