    "notes": "Bei Steigerungen kommt es auf das Verb an: 增加了一倍 (zēngjiāle yí bèi) heißt „um das Einfache gestiegen“, also „verdoppelt“; 增加到两倍 (zēngjiā dào liǎng bèi) heißt „auf das Doppelte gestiegen“. Im genauen Sprachgebrauch ist 增加了两倍 (zēngjiāle liǎng bèi) daher „verdreifacht“, umgangssprachlich wird das aber nicht immer so streng unterschieden. Für Abnahmen benutzt man eher Brüche oder Prozente als 倍: 减少了一半 (jiǎnshǎole yíbàn), 降低了百分之十 (jiàngdīle bǎi fēn zhī shí). Ungefähre Zahlen mit 大约 (dàyuē) oder 左右 (zuǒyòu) sind ein eigener Punkt.",
    "explanation": "Dezimalzahlen: Das Komma wird als 点 (diǎn) gelesen, die Ziffern danach einzeln: 3,14 = 三点一四 (sān diǎn yī sì), 0,5 = 零点五 (líng diǎn wǔ). Brüche: Zuerst kommt der Nenner, dann 分之 (fēn zhī), dann der Zähler – also umgekehrt wie im Deutschen: 三分之一 (sān fēn zhī yī) = „ein Drittel“, 四分之三 (sì fēn zhī sān) = „drei Viertel“. Für „die Hälfte“ sagt man im Alltag meist 一半 (yíbàn). Prozente sind Hundertstel und folgen demselben Muster: 百分之 (bǎi fēn zhī) + Zahl, z. B. 百分之二十 (bǎi fēn zhī èrshí) = „20 %“, 百分之百 (bǎi fēn zhī bǎi) = „hundertprozentig“. Vielfache bildet man mit Zahl + 倍 (bèi): 两倍 (liǎng bèi) = „das Doppelte“, 是……的三倍 = „dreimal so viel wie …“. Typischer Fehler: Zähler und Nenner vertauschen (一分之三 statt 三分之一).",
